starter.css:
h1 {
  text-align: center;
  color: #8B2E2E;
  margin-bottom: 12px;
}
.toolbar {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 16px;
}
.toolbar button {
  padding: 8px 20px;
  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 6px;
  font-size: 13px;
  cursor: pointer;
  color: #3D2B1F;
  transition: all 0.2s;
}
.toolbar button:hover {
  background: #8B2E2E;
  color: #fff;
}
.toolbar button.active {
  background: #8B2E2E;
  color: #fff;
  border-color: #8B2E2E;
}
#gallery {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  min-height: 80px;
}
.card {
  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 10px;
  padding: 20px;
  text-align: center;
  min-width: 150px;
  transition: all 0.3s;
}
.card:hover {
  border-color: #C9A96E;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(61, 43, 31, 0.1);
}
.card h2 {
  color: #8B2E2E;
  margin: 0 0 6px 0;
  font-size: 17px;
}
.card .period {
  color: #C9A96E;
  font-size: 12px;
  font-weight: 600;
}
.card p {
  color: #6B5A4E;
  margin: 4px 0 0 0;
  font-size: 13px;
}
.add-bar {
  text-align: center;
  margin-top: 20px;
}
.add-bar .hint {
  color: #C9A96E;
  font-size: 13px;
  margin-right: 8px;
}
.add-bar button {
  padding: 10px 24px;
  background: #8B2E2E;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  cursor: pointer;
}
.add-bar button:hover {
  background: #C94545;
}

starter.js:
// 作曲家数据（对象数组）
let composers = [
  { name: "巴赫", period: "巴洛克", piece: "赋格的艺术" },
  { name: "莫扎特", period: "古典主义", piece: "魔笛" },
  { name: "贝多芬", period: "古典主义", piece: "命运交响曲" },
  { name: "肖邦", period: "浪漫主义", piece: "夜曲" },
  { name: "舒曼", period: "浪漫主义", piece: "童年情景" },
  { name: "德彪西", period: "印象派", piece: "月光" }
];
let gallery = document.querySelector("#gallery");
// 渲染画廊（接收数组参数）
function showGallery(list) {
  let html = "";
  list.forEach(function(c) {
    html += `
      <div class="card">
        <h2>${c.name}</h2>
        <div class="period">${c.period}</div>
        <p>《${c.piece}》</p>
      </div>
    `;
  });
  gallery.innerHTML = html;
}
// 初始显示全部
showGallery(composers);
// 切换激活按钮样式
function setActive(btn) {
  document.querySelectorAll(".toolbar button").forEach(function(b) {
    b.classList.remove("active");
  });
  btn.classList.add("active");
}
// 筛选按钮
document.querySelector("#showAllBtn").addEventListener("click", function() {
  setActive(this);
  showGallery(composers);
});
document.querySelector("#showRomanticBtn").addEventListener("click", function() {
  setActive(this);
  let filtered = composers.filter(function(c) {
    return c.period === "浪漫主义";
  });
  showGallery(filtered);
});
document.querySelector("#showClassicalBtn").addEventListener("click", function() {
  setActive(this);
  let filtered = composers.filter(function(c) {
    return c.period === "古典主义";
  });
  showGallery(filtered);
});
// 随机添加（预设数据池）
let pool = [
  { name: "柴可夫斯基", period: "浪漫主义", piece: "天鹅湖" },
  { name: "海顿", period: "古典主义", piece: "惊愕交响曲" },
  { name: "拉威尔", period: "印象派", piece: "波莱罗" }
];
let added = 0;
document.querySelector("#addBtn").addEventListener("click", function() {
  if (added < pool.length) {
    composers.push(pool[added]);
    added++;
    showGallery(composers);
  }
});
